package dev.shadw.olympia.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Hoplite with its own model and texture. Generated by shadw-mod mob. */
public class HopliteRenderer extends MobRenderer<Hoplite, HopliteModel.State, HopliteModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("olympia", "textures/entity/hoplite.png");

	public HopliteRenderer(EntityRendererProvider.Context context) {
		super(context, new HopliteModel(context.bakeLayer(HopliteModel.LAYER)), 0.5F);
	}

	@Override
	public HopliteModel.State createRenderState() {
		return new HopliteModel.State();
	}

	@Override
	public void extractRenderState(Hoplite entity, HopliteModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
	}

	@Override
	public ResourceLocation getTextureLocation(HopliteModel.State state) {
		return TEXTURE;
	}
}
